#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"
#include "aclrtlaunch_split.h"

namespace ascend_kernel {

constexpr int64_t CACHE_LINE_BYTE_LENGTH = 512;

at::Tensor split(const at::Tensor &self, int64_t split_size, int64_t dim)
{
    // ---- 输入校验 ----
    TORCH_CHECK(self.scalar_type() == at::kHalf || self.scalar_type() == at::kFloat || self.scalar_type() == at::kBFloat16,
                "split: only float16, bfloat16 and float32 are supported, got ", self.scalar_type());

    int64_t ndim = self.dim();
    TORCH_CHECK(ndim > 0, "split: input tensor must have at least one dimension");

    // 处理负维度
    if (dim < 0) {
        dim += ndim;
    }
    TORCH_CHECK(dim >= 0 && dim < ndim, "split: dim out of range");

    int64_t dimSize = self.size(dim);
    TORCH_CHECK(split_size > 0, "split: split_size must be positive");

    // 计算输出张量数量
    int64_t num_splits = (dimSize + split_size - 1) / split_size;

    // 创建输出张量列表
    std::vector<at::Tensor> outputs;
    outputs.reserve(num_splits);

    int64_t totalOutputElements = 0;
    for (int64_t i = 0; i < num_splits; ++i) {
        int64_t chunk_size = std::min(split_size, dimSize - i * split_size);
        auto sizes = self.sizes().vec();
        sizes[dim] = chunk_size;
        auto out = at::empty(sizes, self.options());
        outputs.push_back(out);
        totalOutputElements += out.numel();
    }

    // 如果没有数据需要搬运，直接返回
    if (self.numel() == 0) {
        return outputs[0];
    }

    // 确保输入是contiguous的
    at::Tensor self_contig = self.contiguous();

    // 计算innerSize (dim维度之后的元素数)
    int64_t innerSize = 1;
    for (int64_t d = dim + 1; d < ndim; ++d) {
        innerSize *= self.size(d);
    }

    // 计算outerSize (dim维度之前的元素数)
    int64_t outerSize = 1;
    for (int64_t d = 0; d < dim; ++d) {
        outerSize *= self.size(d);
    }

    // 构建临时buffer：将split后的数据按正确顺序排列
    // 对于每个chunk，数据在输出中是[outerSize, chunk_size, innerSize]排列
    // 我们需要将输入中对应位置的数据提取到临时buffer中
    at::Tensor tempBuffer = at::empty({totalOutputElements}, self.options());

    int64_t tempOffset = 0;
    for (int64_t i = 0; i < num_splits; ++i) {
        int64_t chunk_size = std::min(split_size, dimSize - i * split_size);
        int64_t chunkNumel = outputs[i].numel();

        // 计算该chunk在输入中的偏移
        int64_t dim_offset = i * split_size;

        // 将输入reshape为[outerSize, dimSize, innerSize]
        // 提取[outerSize, dim_offset:dim_offset+chunk_size, innerSize]的数据
        auto input_view = self_contig.view({outerSize, dimSize, innerSize});
        auto chunk_data = input_view.narrow(1, dim_offset, chunk_size);

        // 将chunk数据复制到临时buffer
        tempBuffer.narrow(0, tempOffset, chunkNumel).copy_(chunk_data.view(-1));
        tempOffset += chunkNumel;
    }

    int64_t totalLength = totalOutputElements;
    int64_t dtypeSize = self.element_size();

    // ---- 获取硬件参数 ----
    auto ascendc_platform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int64_t coreNum = static_cast<int64_t>(ascendc_platform->GetCoreNumAiv());
    uint64_t ubSize;
    ascendc_platform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);
    int64_t ubSizeLimit = static_cast<int64_t>(ubSize);

    // ---- Block 级 tiling (核间切分, Cache Line 对齐) ----
    int64_t totalLengthCore = (totalLength + coreNum - 1) / coreNum;
    int64_t totalLengthCoreAlign = (totalLengthCore * dtypeSize + CACHE_LINE_BYTE_LENGTH - 1)
                                    / CACHE_LINE_BYTE_LENGTH * CACHE_LINE_BYTE_LENGTH / dtypeSize;
    if (totalLengthCoreAlign == 0) {
        totalLengthCoreAlign = 1;
    }

    int64_t usedCoreNum = (totalLength + totalLengthCoreAlign - 1) / totalLengthCoreAlign;
    int64_t formerNum = usedCoreNum - 1;
    int64_t formerLength = totalLengthCoreAlign;
    int64_t tailLength = totalLength - formerNum * formerLength;
    if (tailLength < 0) {
        tailLength = 0;
    }

    // ---- UB 级 tiling (核内切分) ----
    int64_t bufferCoefficient = dtypeSize * 4;
    if (bufferCoefficient == 0) { bufferCoefficient = 1; }
    int64_t maxTileElements = ubSizeLimit / bufferCoefficient;
    if (dtypeSize == 0) { dtypeSize = 1; }
    int64_t alignElements = 32 / dtypeSize;
    if (alignElements == 0) { alignElements = 1; }
    int64_t tileLength = (maxTileElements / alignElements) * alignElements;
    if (tileLength == 0) {
        tileLength = alignElements;
    }

    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);
    if (blockDim == 0) {
        blockDim = 1;
    }

    // 拼接所有输出为一个大的contiguous buffer
    at::Tensor outputConcat = at::empty({totalOutputElements}, self.options());

    // 调用 kernel 搬运数据：将临时buffer的数据搬运到输出buffer
    EXEC_KERNEL_CMD(split, blockDim,
                    tempBuffer, outputConcat,
                    formerNum, formerLength, tailLength, tileLength, dtypeSize);

    // 将outputConcat的数据分发到各个输出张量
    int64_t currentOffset = 0;
    for (int64_t i = 0; i < num_splits; ++i) {
        int64_t chunkNumel = outputs[i].numel();
        auto chunk_data = outputConcat.narrow(0, currentOffset, chunkNumel);
        outputs[i].copy_(chunk_data.view(outputs[i].sizes()));
        currentOffset += chunkNumel;
    }

    // 返回第一个输出张量
    return outputs[0];
}

}  // namespace ascend_kernel
