    import split_ext  # noqa: F401
except ImportError:
    # 兜底：直加载 .so
    if _LIB_PATTERN not in "".join(sys.path):
        import glob as _glob
        _libs = _glob.glob(_LIB_PATTERN)
        if _libs:
            torch.ops.load_library(_libs[0])


class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, x: torch.Tensor, split_size_or_sections, dim: int = 0):
        # 输入校验
        assert x.dtype in (torch.float16, torch.float32, torch.bfloat16)
        assert x.is_contiguous()

        # 调用注册的算子
        # torch.split 返回 tuple，但 AscendC 注册只返回单个 Tensor
        # 这里我们调用注册的 split 算子，返回第一个 chunk
        # 注意：由于 split 返回 tuple，而 AscendC 只能返回单个 Tensor，
        # 实际使用时需要多次调用或使用其他方式处理
        if isinstance(split_size_or_sections, int):
            return torch.ops.npu.split(x, split_size_or_sections, dim)
        else:
            # 对于 list 类型的 split_size_or_sections，使用 PyTorch 参考实现
            return torch.split(x, split_size_or_sections, dim=dim)
