14	constexpr int32_t BUFFER_NUM = 2;
15	
16	template <typename T>
17	class KernelSplit {
18	public:
19	    __aicore__ inline KernelSplit() {}
20	
21	    __aicore__ inline void Init(GM_ADDR x, GM_ADDR y,
22	                                int64_t formerNum, int64_t formerLength,
23	                                int64_t tailLength, int64_t tileLength)
24	    {
25	        int64_t blockIdx = AscendC::GetBlockIdx();
26	
27	        if (blockIdx < formerNum) {
28	            this->blockLength = formerLength;
29	            int64_t offset = formerLength * blockIdx;
30	            xGm.SetGlobalBuffer((__gm__ T *)x + offset, formerLength);
31	            yGm.SetGlobalBuffer((__gm__ T *)y + offset, formerLength);
32	        } else {
33	            this->blockLength = tailLength;
34	            int64_t tailIdx = blockIdx - formerNum;
35	            int64_t offset = formerLength * formerNum + tailLength * tailIdx;
36	            xGm.SetGlobalBuffer((__gm__ T *)x + offset, tailLength);
37	            yGm.SetGlobalBuffer((__gm__ T *)y + offset, tailLength);
38	        }
39	
40	        this->tileLength = tileLength;
41	
42	        pipe.InitBuffer(inQueueX, BUFFER_NUM, tileLength * sizeof(T));
43	        pipe.InitBuffer(outQueueY, BUFFER_NUM, tileLength * sizeof(T));
44	    }
45	
46	    __aicore__ inline void Process()
47	    {
48	        int64_t tileNum = (this->blockLength + this->tileLength - 1) / this->tileLength;
49	        int64_t tailTileLength = this->blockLength - (tileNum - 1) * this->tileLength;
50	
51	        int64_t alignNum = 32 / static_cast<int64_t>(sizeof(T));
52	        int64_t alignedTailLen = ((tailTileLength + alignNum - 1) / alignNum) * alignNum;
53	
54	        for (int64_t i = 0; i < tileNum - 1; ++i) {
55	            CopyIn(i, this->tileLength);
56	            CopyOut(i, this->tileLength);
57	        }
58	        if (tileNum > 0) {
59	            CopyIn(tileNum - 1, alignedTailLen);
60	            CopyOut(tileNum - 1, alignedTailLen);
61	        }
62	    }
63	
64	private:
65	    __aicore__ inline void CopyIn(int64_t progress, int64_t curTileLength)
66	    {
67	        AscendC::LocalTensor<T> xLocal = inQueueX.AllocTensor<T>();
68	        AscendC::DataCopyPad(xLocal, xGm[progress * this->tileLength], curTileLength);
69	        inQueueX.EnQue(xLocal);
70	    }
71	
72	    __aicore__ inline void CopyOut(int64_t progress, int64_t curTileLength)
73	    {
74	        AscendC::LocalTensor<T> xLocal = inQueueX.DeQue<T>();
75	        AscendC::DataCopyPad(yGm[progress * this->tileLength], xLocal, curTileLength);
76	        inQueueX.FreeTensor(xLocal);
77	    }
78	
79	private:
80	    AscendC::TPipe pipe;
81	    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueueX;
82	    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> outQueueY;
83	    AscendC::GlobalTensor<T> xGm;
84	    AscendC::GlobalTensor<T> yGm;
85	    int64_t blockLength;
86	    int64_t tileLength;
87	};
88	
89	extern "C" __global__ __aicore__ void split(GM_ADDR x, GM_ADDR y,
90	                                             int64_t formerNum, int64_t formerLength,
91	                                             int64_t tailLength, int64_t tileLength,
92	                                             int64_t dtypeSize)
93	{
94	    if (dtypeSize == 2) {
95	        KernelSplit<half> op;
96	        op.Init(x, y, formerNum, formerLength, tailLength, tileLength);
97	        op.Process();
98	    } else {
99	        KernelSplit<float> op;
100	        op.Init(x, y, formerNum, formerLength, tailLength, tileLength);
101	        op.Process();
102	    }
103	}
